export function getDeviceMedia(modelName?: string | null): DeviceMedia | null {
  if (!modelName) return null;
  const key = modelName.trim().toLowerCase();
  if (deviceMediaMap[key]) return deviceMediaMap[key];
  
  // Try clean without 'New!'
  const cleanKey = key.replace(/^new!\s*/i, '').trim();
  if (deviceMediaMap[cleanKey]) return deviceMediaMap[cleanKey];

  // Try substring or normalized match
  const normKey = cleanKey.replace(/[^a-z0-9]/g, '');
  for (const k in deviceMediaMap) {
    if (k.replace(/[^a-z0-9]/g, '') === normKey) {
      return deviceMediaMap[k];
    }
  }

  for (const k in deviceMediaMap) {
    const nk = k.replace(/[^a-z0-9]/g, '');
    if (nk.includes(normKey) || normKey.includes(nk)) {
      return deviceMediaMap[k];
    }
  }

  return null;
}
